import java.util.ArrayList;
import java.util.List;

public class AnnotationsDemo {
    static class Animal {
        @Override
        public String toString() { return "Jakies zwierze"; }
    }

    // BEZ @Override - literowka w nazwie to cichy blad
    static class BrokenDog extends Animal {
        public String toStrign() { return "Hau hau!"; } // literowka!
    }

    // Z @Override - kompilator wykryje literowke jesli sie pojawi
    static class CorrectDog extends Animal {
        @Override
        public String toString() { return "Hau hau!"; }
    }

    static class LegacyCalculator {
        @Deprecated(since = "2.1", forRemoval = true)
        public int add(int a, int b) { return a + b; }

        public int addSafely(int a, int b) { return Math.addExact(a, b); }
    }

    public static void main(String[] args) {
        Animal broken = new BrokenDog();
        System.out.println(broken); // "Jakies zwierze" - NIE "Hau hau!"

        Animal correct = new CorrectDog();
        System.out.println(correct); // "Hau hau!"

        LegacyCalculator calc = new LegacyCalculator();
        int sum = calc.add(3, 4); // ostrzezenie kompilatora o @Deprecated

        @SuppressWarnings("unchecked")
        List<String> raw = (List<String>) (List<?>) new ArrayList<Object>();
        raw.add("bezpieczne w tym kontekscie");
        System.out.println(raw);
    }
}
