class MutablePoint implements Cloneable {
    int x, y;
    MutablePoint(int x, int y) { this.x = x; this.y = y; }
    @Override
    protected Object clone() {
        try {
            return (MutablePoint) super.clone();
        } catch (CloneNotSupportedException e) {
            throw new AssertionError(e);
        }
    }
    @Override
    public String toString() { return "(" + x + "," + y + ")"; }
}

MutablePoint original = new MutablePoint(1, 2);
MutablePoint clone = (MutablePoint) original.clone();
clone.x = 99;
System.out.println(original + " " + clone); // (1,2) (99,2)

