interface ModernLogger {
    void log(String message);
}

@Deprecated(since = "1.0", forRemoval = true)
class LegacyLogger {
    void write(String msg) { System.out.println("[LEGACY] " + msg); }
}

class LegacyLoggerAdapter implements ModernLogger {
    private final LegacyLogger legacy = new LegacyLogger();
    @Override
    @SuppressWarnings("deprecation")
    public void log(String message) { legacy.write(message); }
}

new LegacyLoggerAdapter().log("test");
// Adapter pozwala nowemu kodowi korzystac z ModernLogger, jednoczesnie kryjac uzycie przestarzalego API - typowy wzorzec stopniowej migracji.

